// smoke.spec.js — Audio Joiner and Merger: the acceptance checks from SPEC.md on the bundled fictional clips
// (generated by tests/tools/make-audio-fixtures.js): intro-jingle.wav 3 s, episode-one.wav 6 s, outro-theme.wav 3 s.
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');

const fixture = (name) => path.join(__dirname, 'fixtures', name);
const CLIPS = ['intro-jingle.wav', 'episode-one.wav', 'outro-theme.wav'];

async function addClips(page, names = CLIPS) {
  await page.setInputFiles('#file-input', names.map(fixture));
  await expect(page.locator('#track-list > li')).toHaveCount(names.length);
  await expect(page.locator('#join')).toBeEnabled();
}

const rowNames = (page) => page.locator('#track-list .track__name').allTextContents();
const totalSeconds = async (page) => Number(await page.locator('#summary').getAttribute('data-total-seconds'));

// Decodes downloaded audio with the browser's own decoder and returns its duration in seconds.
async function decodedDuration(page, file) {
  const b64 = fs.readFileSync(file).toString('base64');
  return page.evaluate(async (data) => {
    const bytes = Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
    const buf = await new OfflineAudioContext(1, 1, 44100).decodeAudioData(bytes.buffer);
    return buf.duration;
  }, b64);
}

async function joinAndDownload(page) {
  await page.click('#join');
  const dl = page.locator('#download');
  await expect(dl).toBeVisible({ timeout: 30_000 });
  const [download] = await Promise.all([page.waitForEvent('download'), dl.click()]);
  return download;
}

test.describe('Audio Joiner and Merger', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('./');
  });

  test('dropping three sample audio files lists them in order with durations', async ({ page }) => {
    await expect(page.locator('#tracks-empty')).toContainText(/never uploaded/);
    const payload = CLIPS.map((n) => ({ name: n, b64: fs.readFileSync(fixture(n)).toString('base64') }));
    const dt = await page.evaluateHandle((files) => {
      const d = new DataTransfer();
      for (const f of files) d.items.add(new File([Uint8Array.from(atob(f.b64), (c) => c.charCodeAt(0))], f.name, { type: 'audio/wav' }));
      return d;
    }, payload);
    await page.dispatchEvent('#dropzone', 'drop', { dataTransfer: dt });
    await expect(page.locator('#track-list > li')).toHaveCount(3);
    expect(await rowNames(page)).toEqual(CLIPS);
    await expect(page.locator('#track-list .track__dur')).toHaveText(['0:03', '0:06', '0:03']);
    await expect(page.locator('#summary')).toContainText('total 0:12');
    expect(await totalSeconds(page)).toBeCloseTo(12, 1);
    await expect(page.locator('#summary-order')).toHaveText(`Order: ${CLIPS.join(' → ')}`);
  });

  test('reordering the first and last file changes the order in the summary', async ({ page }) => {
    await addClips(page);
    // Buttons: move the last file to the top.
    await page.getByRole('button', { name: 'Move outro-theme.wav up' }).click();
    await page.getByRole('button', { name: 'Move outro-theme.wav up' }).click();
    expect(await rowNames(page)).toEqual(['outro-theme.wav', 'intro-jingle.wav', 'episode-one.wav']);
    // Keyboard: Alt+Down moves the now second row (the old first) to the end.
    await page.locator('#track-list > li').nth(1).focus();
    await page.keyboard.press('Alt+ArrowDown');
    expect(await rowNames(page)).toEqual(['outro-theme.wav', 'episode-one.wav', 'intro-jingle.wav']);
    await expect(page.locator('#summary-order')).toHaveText('Order: outro-theme.wav → episode-one.wav → intro-jingle.wav');
    await expect(page.locator('#track-list > li').nth(2)).toBeFocused();
    // Drag handle: drag the last row back above the first.
    await page.locator('#track-list > li').nth(2).dragTo(page.locator('#track-list > li').nth(0), { targetPosition: { x: 40, y: 4 } });
    await expect(page.locator('#summary-order')).toHaveText('Order: intro-jingle.wav → outro-theme.wav → episode-one.wav');
    // Delete removes the focused row; the total updates.
    await page.locator('#track-list > li').nth(1).focus();
    await page.keyboard.press('Delete');
    await expect(page.locator('#summary-order')).toHaveText('Order: intro-jingle.wav → episode-one.wav');
    expect(await totalSeconds(page)).toBeCloseTo(9, 1);
  });

  test('pressing Join downloads one MP3 whose duration is about the sum of the parts', async ({ page }) => {
    await addClips(page);
    await expect(page.locator('#format')).toHaveValue('mp3');
    await expect(page.locator('#out-name')).toHaveValue('joined');
    const download = await joinAndDownload(page);
    expect(download.suggestedFilename()).toBe('joined.mp3');
    const file = await download.path();
    const bytes = fs.readFileSync(file);
    expect(bytes.length).toBeGreaterThan(50_000); // 12 s at 192 kbps is about 288 KB
    expect(bytes[0]).toBe(0xff);
    expect(bytes[1] & 0xe0).toBe(0xe0); // MPEG frame sync
    const seconds = await decodedDuration(page, file);
    expect(Math.abs(seconds - 12)).toBeLessThan(0.25);
    await expect(page.locator('.join-result .result__info')).toContainText('0:12');
    await expect(page.locator('.join-result audio')).toHaveAttribute('src', /^blob:/);
    await expect(page.locator('#progress-label')).toContainText('100%');
  });

  test('a crossfade of 2 seconds makes the total shorter by about 2 seconds per join', async ({ page }) => {
    await addClips(page);
    const plain = await totalSeconds(page);
    await page.fill('#crossfade', '2');
    await expect(page.locator('#gap')).toBeDisabled();
    await expect(page.locator('#summary')).toContainText('total 0:08');
    expect(plain - (await totalSeconds(page))).toBeCloseTo(4, 1); // two joins
    // WAV output gives an exact frame count to check the real result, not just the summary.
    await page.selectOption('#format', 'wav');
    await page.fill('#out-name', 'mixtape');
    const download = await joinAndDownload(page);
    expect(download.suggestedFilename()).toBe('mixtape.wav');
    const bytes = fs.readFileSync(await download.path());
    expect(bytes.toString('ascii', 0, 4)).toBe('RIFF');
    const channels = bytes.readUInt16LE(22);
    const rate = bytes.readUInt32LE(24);
    expect(rate).toBe(44100); // follows the first file; the 22.05 and 32 kHz clips were resampled
    expect(channels).toBe(2); // the stereo outro makes the output stereo
    const seconds = (bytes.length - 44) / (channels * 2) / rate;
    expect(seconds).toBeCloseTo(8, 1);
    // Clamping keeps every sample in range and the crossfade region is not silent.
    // 2 s in is the middle of the first crossfade (1 s to 3 s): both tones at half gain, so clearly audible.
    const at = (sec) => 44 + Math.round(sec * rate) * channels * 2;
    let peak = 0;
    for (let o = at(2); o < at(2.05); o += channels * 2) peak = Math.max(peak, Math.abs(bytes.readInt16LE(o)));
    expect(peak).toBeGreaterThan(3000);
    expect(peak).toBeLessThanOrEqual(32767);
  });

  test('a non audio file is rejected with a message, also when mixed with valid files', async ({ page }) => {
    await page.setInputFiles('#file-input', [fixture('sample.png'), fixture('intro-jingle.wav'), fixture('sample.pdf')]);
    const alert = page.locator('#results .alert.alert--error');
    await expect(alert).toBeVisible();
    await expect(alert).toContainText('not audio files');
    await expect(alert).toContainText('sample.png');
    await expect(alert).toContainText('sample.pdf');
    await expect(page.locator('#track-list > li')).toHaveCount(1);
    await expect(page.locator('#join')).toBeEnabled();
    // A file that claims to be audio but cannot be decoded is flagged on its own row and skipped.
    await page.setInputFiles('#file-input', { name: 'broken.mp3', mimeType: 'audio/mpeg', buffer: Buffer.from('this is not really audio data at all') });
    const bad = page.locator('#track-list > li').nth(1);
    await expect(bad.locator('.track__error')).toBeVisible();
    await expect(bad.locator('.track__error')).toContainText('could not decode');
    await expect(page.locator('#summary')).toContainText('1 file · total 0:03');
  });

  test('works at 390px wide: list, Enter to join and download without horizontal scroll', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    await addClips(page, [...CLIPS, 'intro-jingle.wav']); // a duplicate name is allowed
    await expect(page.locator('#track-list > li')).toHaveCount(4);
    await page.locator('#track-list > li').first().focus();
    await page.keyboard.press('Enter');
    await expect(page.locator('#download')).toBeVisible({ timeout: 30_000 });
    await expect(page.locator('#download')).toBeInViewport();
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win + 1);
    for (const sel of ['#join', '#out-name', '#crossfade', '#download', '#track-list > li']) {
      const box = await page.locator(sel).first().boundingBox();
      expect(box.x).toBeGreaterThanOrEqual(0);
      expect(box.x + box.width).toBeLessThanOrEqual(391);
    }
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download')]);
    expect(download.suggestedFilename()).toBe('joined.mp3');
  });

  test('__demo shows a finished join of the three demo clips', async ({ page }) => {
    await page.evaluate(() => window.__demo());
    await expect(page.locator('#track-list > li')).toHaveCount(3);
    await expect(page.locator('#download')).toHaveText('Download joined.mp3');
    await expect(page.locator('.join-result .result__info')).toContainText('0:10');
  });
});
